package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaKnDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("ಮೊದಲ ಹಣ್ಣನ್ನು ನೋಡುವುದು", "ಓ ಅಲ್ಲಾಹನೇ, ನಮ್ಮ ಹಣ್ಣಿನಲ್ಲಿ ನಮ್ಮನ್ನು ಆಶೀರ್ವದಿಸಿರಿ, ನಮ್ಮ ನಗರದಲ್ಲಿ ನಮ್ಮನ್ನು ಆಶೀರ್ವದಿಸಿರಿ ಮತ್ತು ನಮ್ಮ ಸ'ಮತ್ತು ನಮ್ಮ ಮಡ (ಅಳತೆಗಳು) ಯಲ್ಲಿ ನಮ್ಮನ್ನು ಆಶೀರ್ವದಿಸಿರಿ.", "ಋತುವಿನ ಮೊದಲ ಹಣ್ಣನ್ನು ನೋಡಿದ ಮೇಲೆ.", "ಒಂದು ನಗರದಲ್ಲಿ ಮತ್ತು ಒಂದು ಸ್ಥಳದಲ್ಲಿ ಆಶೀರ್ವಾದಕ್ಕಾಗಿ ಒಂದು ದುಆ."),
        "dua_good_news" to DuaText("ಸಂತೋಷದ ಸುದ್ದಿ", "ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ಅಲ್ಲಾಹನಿಗೇ, ಆತನ ಅನುಗ್ರಹದಿಂದ ಒಳ್ಳೆಯವುಗಳು ಪೂರ್ಣಗೊಳ್ಳುತ್ತವೆ.", "ಒಳ್ಳೆಯ ಸುದ್ದಿ ಬಂದ ಮೇಲೆ (ಮತ್ತು ಕೃತಜ್ಞತೆಯ ಸಾಷ್ಟಾಂಗ ನಮಸ್ಕಾರವನ್ನು ಮಾಡಿ).", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ತಮಗೆ ಇಷ್ಟವಾದದ್ದನ್ನು ನೋಡಿದ ನಂತರ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_looking_mirror" to DuaText("ಕನ್ನಡಿಯಲ್ಲಿ ನೋಡುತ್ತಾ", "ಓ ಅಲ್ಲಾಹನೇ, ನೀನು ನನ್ನ ನೋಟವನ್ನು ಹೇಗೆ ಚೆನ್ನಾಗಿದ್ದೀಯೋ ಹಾಗೆಯೇ ನನ್ನ ಪಾತ್ರವನ್ನೂ ಚೆನ್ನಾಗಿ ಮಾಡಿ.", "ಕನ್ನಡಿಯಲ್ಲಿ ನೋಡುವಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಈ ದುಆವನ್ನು ಮಾಡಿದರು (ಇದು ಕನ್ನಡಿಯ ಉಲ್ಲೇಖವಿಲ್ಲದೆ ಸಹ ಸ್ಥಾಪಿಸಲ್ಪಟ್ಟಿದೆ)."),
        "dua_rabbana_taqabbal" to DuaText("ಕಾರ್ಯಗಳ ಸ್ವೀಕಾರ", "ನಮ್ಮ ಒಡೆಯನೇ, ನಮ್ಮಿಂದ ಇದನ್ನು ಸ್ವೀಕರಿಸು. ನಿಶ್ಚಯವಾಗಿಯೂ ನೀನು ಎಲ್ಲವನ್ನೂ ಕೇಳುವವನಾಗಿ, ಎಲ್ಲವನ್ನೂ ಬಲ್ಲವನಾಗಿದ್ದೀ. ಮತ್ತು ನಮ್ಮ ಪಶ್ಚಾತ್ತಾಪವನ್ನು ಸ್ವೀಕರಿಸು. ನಿಶ್ಚಯವಾಗಿಯೂ ನೀನು ಪಶ್ಚಾತ್ತಾಪವನ್ನು ಮಾಡುವವನಾಗಿ, ಕರುಣಾಮಯಿಗನಾಗಿದ್ದೀ.", "ಕಾಬಾ ನಿರ್ಮಿಸುವಾಗ ಇಬ್ರಾಹಿಂ ಮತ್ತು ಇಸ್ಮಾಯಿಲ್ (ಎ. ಎಸ್) ಕೇಳಿದರು.", "ಪ್ರತಿ ಒಳ್ಳೆಯ ಕೆಲಸದ ನಂತರ ಸ್ವೀಕಾರಕ್ಕಾಗಿ ಒಂದು ದುಆ."),
        "dua_muawwidhat" to DuaText("ಮೂರು ಕುಲಗಳು (ಮುಆವ್ವಿಧತ್)", "(ಸೂರಹ್ ಅಲ್-ಇಖ್ಲಾಸ್) ಹೇಳಿಃ ಆತನೇ ಅಲ್ಲಾಹ್, ಒಬ್ಬನೇ. ಅಲ್ಲಾಹನು, ಸ್ವಾವಲಂಬಿಯಾಗಿದ್ದಾನೆ. ಆತನು ಹುಟ್ಟುವುದೂ ಇಲ್ಲ, ಹುಟ್ಟುವುದೂ ಇಲ್ಲ. ಮತ್ತು ಆತನಿಗೆ ಸರಿಸಮಾನನಾದವನು ಯಾರೂ ಇಲ್ಲ.\n\n(ಸೂರಹ್ ಅಲ್-ತಲಾಖ್) ಹೇಳಿಃ ನಾನು ಬೆಳಗಿನ ಜಾವದ ಒಡೆಯನಲ್ಲಿ, ಆತನು ಸೃಷ್ಟಿಸಿದ ದುಷ್ಟತನದಿಂದ, ಅದು ನೆಲೆಗೊಂಡಾಗ ಕತ್ತಲೆಯ ದುಷ್ಟತನದಿಂದ, ಗಂಟುಗಳ ಮೇಲೆ ಬೀಸುವವರ ದುಷ್ಟತನದಿಂದ ಮತ್ತು ಅಸೂಯೆಪಡುವವನ ದುಷ್ಟತನದಿಂದ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.\n\n(ಸೂರಹ್-ಅನ್ಸ) ಹೇಳಿಃ ನಾನು ಮನುಷ್ಯರ ಒಡೆಯ, ಮಾನವಕುಲದ ರಾಜ, ಮಾನವಕುಲದ ದೇವರಲ್ಲಿ, ಹಿಂತಿರುಗುವ ಪಿಸುಗುಟ್ಟುವವನ ದುಷ್ಟತನದಿಂದ, ಜಿನ್ನರು ಮತ್ತು ಮಾನವಕುಲದ ನಡುವೆ ಮನುಷ್ಯರ ಹೃದಯಗಳಲ್ಲಿ ಪಿಸುಗುಟ್ಟುವವನಿಂದ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಮೂರು ಸೂರಾಗಳು ಪ್ರತಿ ದಿನ ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಸಂಜೆ ಮೂರು ಬಾರಿ, ಮತ್ತು ಮಲಗುವ ಮೊದಲು, ಕೈಗಳಿಗೆ ಬೀಸುತ್ತವೆ ಮತ್ತು ಅವುಗಳನ್ನು ದೇಹದ ಮೇಲೆ ಒರೆಸುತ್ತವೆ.", "ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಸಂಜೆ ಮೂರು ಬಾರಿ ಅವುಗಳನ್ನು ಪಠಿಸಿದರೆ ಸಾಕು."),
        "dua_sabr" to DuaText("ತಾಳ್ಮೆ ಮತ್ತು ಸ್ಥಿರತೆಗಾಗಿ", "ನಮ್ಮ ಒಡೆಯನೇ, ನಮ್ಮ ಮೇಲೆ ತಾಳ್ಮೆಯನ್ನು ಸುರಿಸು, ನಮ್ಮ ಪಾದಗಳನ್ನು ದೃಢಗೊಳಿಸಿ ಮತ್ತು ಅವಿಶ್ವಾಸಿಗಳ ವಿರುದ್ಧ ನಮಗೆ ಸಹಾಯ ಮಾಡು.", "ಕಷ್ಟ ಮತ್ತು ಸಂಘರ್ಷದ ಸಮಯದಲ್ಲಿ.", "ತಲುತ್ನ ಸೈನ್ಯದ ದುಆ."),
        "dua_rabbana_innana_amanna" to DuaText("ಕ್ಷಮೆ ಮತ್ತು ಬೆಂಕಿಯಿಂದ ರಕ್ಷಣೆ", "ಓ ನಮ್ಮ ಒಡೆಯನೇ, ನಾವು ನಂಬಿಕೆಯಿಟ್ಟಿದ್ದೇವೆ. ಆದ್ದರಿಂದ ನಮ್ಮ ಪಾಪಗಳನ್ನು ಕ್ಷಮಿಸು ಮತ್ತು ನರಕದ ಶಿಕ್ಷೆಯಿಂದ ನಮ್ಮನ್ನು ರಕ್ಷಿಸು.", "ಕುರಾನ್ ಧರ್ಮ.", "ದೇವಭಯದ ಗುಣಗಳಲ್ಲಿ ಒಂದು ದುಆ ಉಲ್ಲೇಖಿಸಲಾಗಿದೆ."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("ನಮ್ಮ ವ್ಯವಹಾರದಲ್ಲಿ ಮಾರ್ಗದರ್ಶನ (ಆಶಾಬ್ ಅಲ್-ಕಹ್ಫ್)", "ನಮ್ಮ ಒಡೆಯನೇ, ನಮಗೆ ನಿನ್ನ ಕರುಣೆಯನ್ನು ಕರುಣಿಸು ಮತ್ತು ನಮ್ಮ ವ್ಯವಹಾರದಲ್ಲಿ ನಮಗೆ ಸರಿಯಾದ ಮಾರ್ಗದರ್ಶನವನ್ನು ಸಿದ್ಧಪಡಿಸಿ.", "ಗುಹೆಯ ಜನರ ದುಆ.", "ನಿರ್ಧಾರಗಳು ಮತ್ತು ಕಷ್ಟಕರ ಸಂದರ್ಭಗಳಲ್ಲಿ ಮಾರ್ಗದರ್ಶನ."),
        "dua_musa_faqir" to DuaText("ನಿಬಂಧನೆಗಾಗಿ ಮೂಸಾದ ದುವಾ (ಎ. ಎಸ್)", "ನನ್ನ ಒಡೆಯನೇ, ನೀನು ನನಗೆ ಕಳುಹಿಸುವ ಯಾವುದೇ ಒಳ್ಳೆಯದರ ಅಗತ್ಯ ನನಗೆ ನಿಜವಾಗಿಯೂ ಇದೆ.", "ಉಪಬಂಧ ಮತ್ತು ಒಳ್ಳೆಯದನ್ನು ಹುಡುಕುವುದು-ಮಾದ್ಯಾನ್ನಲ್ಲಿ ಮೂಸಾದ (ಎ. ಎಸ್) ದುಆ.", "ಈ ದುಆದ ನಂತರ, ಅಲ್ಲಾಹನು ಮೂಸಾದ (ಅ. ಸ.) ಗೆ ಮನೆ, ಕೆಲಸ ಮತ್ತು ಹೆಂಡತಿಯನ್ನು ನೀಡಿದನು."),
        "dua_ayyub" to DuaText("ಅನಾರೋಗ್ಯದಲ್ಲಿದ್ದ ಅಯ್ಯೂಬ್ (ಎ. ಎಸ್) ನ ದುವಾ", "(ನನ್ನ ಒಡೆಯನೇ,) ನನಗೆ ಹಾನಿ ಉಂಟಾಗಿದೆ ಮತ್ತು ನೀನು ಕರುಣೆಯುಳ್ಳವರಲ್ಲಿ ಅತ್ಯಂತ ಕರುಣಾಮಯಿ.", "ಅನಾರೋಗ್ಯ ಮತ್ತು ಯಾತನೆಗಳಲ್ಲಿ.", "ಅಲ್ಲಾಹು ಅಯ್ಯೂಬ್ (ಅ. ಸ.) ನ ನೋವನ್ನು ತೆಗೆದುಹಾಕಿದನು."),
        "dua_husn_khatimah" to DuaText("ಮುಸ್ಲಿಮನಾಗಿ ಸಾಯಿರಿ (ಯೂಸುಫ್ ಎ. ಎಸ್)", "ಆಕಾಶಗಳ ಮತ್ತು ಭೂಮಿಯ ಸೃಷ್ಟಿಕರ್ತನೇ, ನೀನು ಈ ಲೋಕದಲ್ಲಿ ಮತ್ತು ಪರಲೋಕದಲ್ಲಿ ನನ್ನ ರಕ್ಷಕನಾಗಿದ್ದೀ. ನನ್ನನ್ನು ಮುಸ್ಲಿಮನಾಗಿ ಸಾಯಿಸಿ, ಮತ್ತು ಸದ್ಗುಣಶೀಲರೊಂದಿಗೆ ನನ್ನೊಂದಿಗೆ ಸೇರಿಕೊಳ್ಳಿ.", "ಒಳ್ಳೆಯ ಅಂತ್ಯಕ್ಕೆ ಒಂದು ಡುವಾ.", "ಪ್ರವಾದಿ ಯೂಸುಫ್ (ಅ. ಸ.) ಅವರ ದೂ."),
        "dua_shaitan_hamazat" to DuaText("ದೆವ್ವಗಳ ವಿಸ್ಪರ್ಸ್ನಿಂದ ಆಶ್ರಯ", "ನನ್ನ ಒಡೆಯನೇ, ದೆವ್ವಗಳ ಪಿಸುಗುಟ್ಟುವಿಕೆಯಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ ಮತ್ತು ನನ್ನ ಒಡೆಯನೇ, ಅವರು ನನ್ನ ಹತ್ತಿರ ಬರದಂತೆ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಸೈತಾನನ ಪಿಸುಗುಟ್ಟುವಿಕೆಯಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ.", "ಆಶ್ರಯ ಪಡೆಯುವ ಕುರಾನ್ ದ್ವಂದ್ವ."),
        "dua_bad_character" to DuaText("ಕೆಟ್ಟ ಗುಣಗಳಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ಕೆಟ್ಟ ಸ್ವಭಾವ, ಕೆಟ್ಟ ಕಾರ್ಯಗಳು ಮತ್ತು ಕೆಟ್ಟ ಆಸೆಗಳಿಂದ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಕೆಟ್ಟ ಸ್ವಭಾವ, ಕಾರ್ಯಗಳು ಮತ್ತು ಆಸೆಗಳಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರಿಂದ ಆಶ್ರಯ ಪಡೆದಿರುವ ಒಂದು ದುಆ."),
        "dua_zawal_nimah" to DuaText("ಆಶೀರ್ವಾದಗಳ ನಷ್ಟದಿಂದ ನಿರಾಶ್ರಿತರಾದವರು", "ಓ ಅಲ್ಲಾಹನೇ, ನಿನ್ನ ಆಶೀರ್ವಾದದ ನಷ್ಟದಿಂದ, ನೀನು ನೀಡಿದ ಯೋಗಕ್ಷೇಮದ ಬದಲಾವಣೆಯಿಂದ, ನಿನ್ನ ಹಠಾತ್ ಶಿಕ್ಷೆಯಿಂದ ಮತ್ತು ನಿನ್ನ ಎಲ್ಲಾ ಅಸಮಾಧಾನದಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಆಶೀರ್ವಾದ ಕಳೆದುಕೊಳ್ಳುವುದರಿಂದ ಮತ್ತು ಹಠಾತ್ ವಿಪತ್ತಿನಿಂದ ನಿರಾಶ್ರಿತರಾಗಿರಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರ ಒಂದು ದುಆ."),
        "dua_useless_knowledge" to DuaText("ಪ್ರಯೋಜನವಿಲ್ಲದ ಜ್ಞಾನದಿಂದ ಆಶ್ರಯ", "ಓ ಅಲ್ಲಾಹನೇ, ಪ್ರಯೋಜನವಿಲ್ಲದ ಜ್ಞಾನದಿಂದ, ಭಯವಿಲ್ಲದ ಹೃದಯದಿಂದ, ಎಂದಿಗೂ ತೃಪ್ತಿಯಾಗದ ಆತ್ಮದಿಂದ ಮತ್ತು ಉತ್ತರಿಸದ ದ್ವಾಯದಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ವ್ಯರ್ಥವಾದ ಜ್ಞಾನದಿಂದ ಮತ್ತು ಅಲ್ಲಾಹನಿಗೆ ಭಯವಿಲ್ಲದ ಹೃದಯದಿಂದ ಆಶ್ರಯ ಪಡೆಯಿರಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಂ ಅವರಿಂದ ಆಶ್ರಯ ಪಡೆದಿರುವ ಒಂದು ದುಆ."),
        "dua_beneficial_knowledge" to DuaText("ಪ್ರಯೋಜನಕಾರಿ ಜ್ಞಾನ ಮತ್ತು ಹಲಾಲ್ ರಿಜಕ್", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನಗೆ ಪ್ರಯೋಜನಕಾರಿ ಜ್ಞಾನ, ಶುದ್ಧವಾದ ಪೋಷಣೆ ಮತ್ತು ಸ್ವೀಕೃತ ಕಾರ್ಯಗಳನ್ನು ಕೋರುತ್ತೇನೆ.", "ಫಜ಼್ರ್ ಪ್ರಾರ್ಥನೆಯ ನಂತರ.", "ಫಜರಿನ ಸಲಾಂ ನಂತರ ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_leprosy_diseases" to DuaText("ಗಂಭೀರ ಕಾಯಿಲೆಗಳಿಂದ ನಿರಾಶ್ರಿತರಾದವರು", "ಓ ಅಲ್ಲಾಹ್ವೇ, ನಾನು ನಿಮ್ಮಲ್ಲಿ ಕೋಡಂಗಿ, ಹುಚ್ಚು, ಕುಷ್ಠರೋಗ ಮತ್ತು ಎಲ್ಲಾ ದುಷ್ಟ ಕಾಯಿಲೆಗಳಿಂದ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಗಂಭೀರ ಕಾಯಿಲೆಗಳಿಂದ ರಕ್ಷಣೆ.", "ಆರೋಗ್ಯವನ್ನು ಕಾಪಾಡಿಕೊಳ್ಳಲು ಸುನ್ನತ್ ದುಆ."),
        "dua_fear_people" to DuaText("ಶತ್ರುಗಳು ಅಥವಾ ದಬ್ಬಾಳಿಕೆಯ ಭಯ", "ಓ ಅಲ್ಲಾಹನೇ, ನಾವು ನಿನ್ನನ್ನು ಅವರ ಮುಂದೆ ನಿಲ್ಲಿಸುತ್ತೇವೆ ಮತ್ತು ಅವರ ದುಷ್ಟತನದಿಂದ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯ ಪಡೆಯುತ್ತೇವೆ.", "ಜನರು ಅಥವಾ ವ್ಯಕ್ತಿಯ ಹಾನಿಯ ಭಯದಿಂದ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಜನರಿಗೆ ಹೆದರುತ್ತಿದ್ದಾಗ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_shirk_protection" to DuaText("ಹಿಡನ್ ಶಿರ್ಕ್ನಿಂದ ರಕ್ಷಣೆ", "ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ನಿನಗೆ ತಿಳಿದುಕೊಂಡು ಯಾವುದನ್ನಾದರೂ ಸಂಗಡಪಡಿಸದಂತೆ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ ಮತ್ತು ನಾನು ತಿಳಿಯದೆ ಏನು ಮಾಡುತ್ತೇನೋ ಅದಕ್ಕಾಗಿ ನಿನ್ನನ್ನು ಕ್ಷಮಿಸುತ್ತೇನೆ.", "ತೋರಿಸುವ ಮತ್ತು ಗುಪ್ತ ಶಿರ್ಕ್ನಿಂದ ಸುರಕ್ಷಿತವಾಗಿರಲು.", "ಇರುವೆಗಳ ಹರಿವುಗಿಂತ ಹಿಡನ್ ಶಿರ್ಕ್ ಹೆಚ್ಚು ಗುಪ್ತವಾಗಿದೆ."),
        "dua_rain" to DuaText("ಮಳೆ ಬಂದಾಗ", "ಓ ಅಲ್ಲಾಹನೇ, (ಒಳ್ಳೆಯ ಮಳೆಯನ್ನು) ಕಳುಹಿಸು.", "ಮಳೆ ಬಂದಾಗ.", "ಮಳೆ ಎಂದರೆ ದುಆಗಳನ್ನು ಸ್ವೀಕರಿಸುವ ಸಮಯ."),
        "dua_after_rain" to DuaText("ಮಳೆಯ ನಂತರ", "ಅಲ್ಲಾಹುವಿನ ಅನುಗ್ರಹ ಮತ್ತು ಕರುಣೆಯಿಂದ ನಮಗೆ ಮಳೆ ಬಂದಿದೆ.", "ಮಳೆಯ ನಂತರ.", "ಇದನ್ನು ಹೇಳುವವನು ಅಲ್ಲಾಹನಲ್ಲಿ ನಂಬಿಕೆಯುಳ್ಳವನು."),
        "dua_istisqa" to DuaText("ಮಳೆಗಾಗಿ ಕೇಳುವುದು (ಇಸ್ತಿಸ್ಕಾ)", "ಓ ಅಲ್ಲಾಹನೇ, ನಮಗೆ ಮೂರು ಬಾರಿ ಮಳೆಯನ್ನು ಕಳುಹಿಸು.", "ಮಳೆ ಇಲ್ಲದಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಶುಕ್ರವಾರದ ಧರ್ಮೋಪದೇಶದಲ್ಲಿ ಈ ದುಆ ಮಾಡಿದರು ಮತ್ತು ಮಳೆ ಸುರಿಯಿತು."),
        "dua_heavy_rain" to DuaText("ಅತಿಯಾದ ಮಳೆ", "ಓ ಅಲ್ಲಾಹನೇ, (ಅದು ಬೀಳಲಿ) ನಮ್ಮ ಸುತ್ತಲೂ, ನಮ್ಮ ಮೇಲೆ ಅಲ್ಲ.", "ತುಂಬಾ ಮಳೆ ಬಂದಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರ ದ್ವಾಯದ ಮೂಲಕ ಮೋಡಗಳು ದೂರ ಹೋದವು."),
        "dua_wind" to DuaText("ಗಾಳಿ ಬೀಸುವಾಗ", "ಓ ಅಲ್ಲಾಹನೇ, ಅದರ ಒಳಿತಿಗಾಗಿ, ಒಳಿತಿಗಾಗಿ ಮತ್ತು ಅದರೊಂದಿಗೆ ಕಳುಹಿಸಲಾದ ಒಳಿತಿಗಾಗಿ ನಾನು ನಿನ್ನನ್ನು ಕೇಳಿಕೊಳ್ಳುತ್ತೇನೆ ಮತ್ತು ಅದರ ಒಳಿತಿನಿಂದ, ಒಳಗಿನ ಕೆಡುಕಿನಿಂದ ಮತ್ತು ಅದರೊಂದಿಗೆ ಕಳುಹಿಸಲಾದ ಕೆಡುಕಿನಿಂದ ನಾನು ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಬಲವಾದ ಗಾಳಿ ಅಥವಾ ಚಂಡಮಾರುತ ಬೀಸುವಾಗ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸ್ಲಮ್ ಅವರು ಬಿರುಗಾಳಿಗಳ ಸಮಯದಲ್ಲಿ ಈ ದುಆವನ್ನು ಮಾಡಿದರು."),
        "dua_thunder" to DuaText("ಕಿಡಿಗೇಡಿಗಳ ಸದ್ದು", "ಗುಡುಗು ತನ್ನ ಸ್ತುತಿಯಿಂದ ಮಹಿಮೆಪಡಿಸುವವನಿಗೆ ಮತ್ತು ದೇವತೆಗಳಿಗೆ ಆತನ ಭಯದಿಂದ ಮಹಿಮೆ ಇರಲಿ.", "ಗುಡುಗು ಕೇಳಿದ ಮೇಲೆ-ಅಬ್ದುಲ್ಲಾ ಇಬ್ನ್ ಅಜ್-ಜುಬೈರ್ (ಆರ್. ಎ.) ಅವರ ಅಭ್ಯಾಸ.", "ಸೂರಹ್ ಅರ್-ರಾದ್ (13:13) ನಿಂದ ತೆಗೆದುಕೊಳ್ಳಲಾಗಿದೆ."),
        "dua_new_moon" to DuaText("ಅಮಾವಾಸ್ಯೆಯನ್ನು ನೋಡುವುದು", "ಓ ಅಲ್ಲಾಹನೇ, ಈ ಚಂದ್ರನು ನಮ್ಮ ಮೇಲೆ ಆಶೀರ್ವಾದ, ನಂಬಿಕೆ, ಸುರಕ್ಷತೆ ಮತ್ತು ಇಸ್ಲಾಂನೊಂದಿಗೆ ಉದಯಿಸಲಿ. (ಚಂದ್ರನೇ,) ನನ್ನ ಒಡೆಯನು ಮತ್ತು ನಿನ್ನ ಒಡೆಯನು ಅಲ್ಲಾಹನೇ.", "ಅಮಾವಾಸ್ಯೆಯನ್ನು ನೋಡಿದಾಗ.", "ಪ್ರತಿ ಹೊಸ ತಿಂಗಳೂ ಸುನ್ನಾ ದುಆ."),
        "dua_janaza_adult" to DuaText("ಜನಾಜಾ ಪ್ರಾರ್ಥನೆ (ವಯಸ್ಕರು)", "ಓ ಅಲ್ಲಾಹನೇ, ನಮ್ಮ ಜೀವಂತ ಮತ್ತು ನಮ್ಮ ಸತ್ತವರನ್ನು, ಅಲ್ಲಿದ್ದ ಮತ್ತು ಇಲ್ಲದವರನ್ನು, ನಮ್ಮ ಯುವಕರನ್ನು ಮತ್ತು ನಮ್ಮ ವೃದ್ಧರನ್ನು, ನಮ್ಮ ಪುರುಷರನ್ನು ಮತ್ತು ನಮ್ಮ ಮಹಿಳೆಯರನ್ನು ಕ್ಷಮಿಸು. ಓ ಅಲ್ಲಾಹನೇ, ನಮ್ಮಲ್ಲಿ ಯಾರನ್ನಾದರೂ ನೀನು ಜೀವಂತವಾಗಿರಿಸಿಕೊಂಡರೂ, ಅವನನ್ನು ಇಸ್ಲಾಂನಲ್ಲಿ ಜೀವಂತವಾಗಿರಿಸು. ಮತ್ತು ನಮ್ಮಲ್ಲಿ ಯಾರನ್ನು ನೀನು ಸಾಯಿಸುತ್ತೀಯೋ, ಅವನನ್ನು ನಂಬಿಕೆಯಿಂದ ಸಾಯಿಸು.", "ಅಂತ್ಯಕ್ರಿಯೆಯ ಪ್ರಾರ್ಥನೆಯ ಮೂರನೇ ತಕ್ಬೀರ್ ನಂತರ.", "ಮೃತ ವಯಸ್ಕರಿಗೆ ಸುನ್ನಾಹ್ ದುಆ."),
        "dua_janaza_child" to DuaText("ಜನಾಜಾ ಪ್ರಾರ್ಥನೆ (ಮಗು)", "ಓ ಅಲ್ಲಾಹನೇ, ಅವನನ್ನು ನಮಗೆ ಮುಂಚೂಣಿಯವನನ್ನಾಗಿ (ಮತ್ತು ಆಶ್ರಯದಾತನಾಗಿ) ಮಾಡಿ, ಅವನಿಗೆ ಪ್ರತಿಫಲ ಮತ್ತು ನಿಧಿ ನೀಡಿ, ಮತ್ತು ಅವನನ್ನು ನಮಗೆ ಮಧ್ಯಸ್ಥಿಕೆಯ ಮಧ್ಯಸ್ಥಿಕೆಯನ್ನಾಗಿ ಮಾಡಿ, ಅವನ ಮಧ್ಯಸ್ಥಿಕೆಯನ್ನು ಸ್ವೀಕರಿಸಲಾಗುತ್ತದೆ.", "ಮಗುವಿನ ಅಂತ್ಯಕ್ರಿಯೆಯ ಪ್ರಾರ್ಥನೆಯಲ್ಲಿ (ಹುಡುಗಿಯೊಬ್ಬಳು'ಇಜ್'ಆಲ್ಹಾ'ಎಂದು ಹೇಳುತ್ತಾಳೆ).", "ಹನಾಫಿಗಳು ಸುನ್ನಾ ದುಆವನ್ನು ಅಭ್ಯಾಸ ಮಾಡುತ್ತಿದ್ದರು."),
        "dua_mayyit_awf" to DuaText("ಮೃತರಿಗೆ ವಿವರವಾದ ದುವಾ", "ಓ ಅಲ್ಲಾಹನೇ, ಅವನನ್ನು ಕ್ಷಮಿಸು, ಅವನ ಮೇಲೆ ಕರುಣೆ ತೋರಿಸು, ಅವನಿಗೆ ಕ್ಷೇಮವನ್ನು ಕೊಡು ಮತ್ತು ಅವನನ್ನು ಕ್ಷಮಿಸು. ಅವನ ಸ್ವಾಗತವನ್ನು ಗೌರವಾನ್ವಿತವಾಗಿಸಿ ಮತ್ತು ಅವನ ಸಮಾಧಿಯನ್ನು ವಿಶಾಲವಾಗಿಸಿ, ಅವನನ್ನು ನೀರು, ಹಿಮ ಮತ್ತು ಆಲಿಕಲ್ಲುಗಳಿಂದ ತೊಳೆಯಿರಿ ಮತ್ತು ಬಿಳಿ ಉಡುಪನ್ನು ಕೊಳಕುಗಳಿಂದ ಶುದ್ಧೀಕರಿಸಿದಂತೆ ಅವನನ್ನು ಪಾಪಗಳಿಂದ ಶುದ್ಧಗೊಳಿಸಿ.", "ಅಂತ್ಯಕ್ರಿಯೆಯ ಪ್ರಾರ್ಥನೆಯಲ್ಲಿ ಅಥವಾ ಮೃತರಿಗಾಗಿ.", "ಅವ್ಫ್ ಇಬ್ನ್ ಮಲಿಕ್ (ರ.) ಅವರು ಆ ಮೃತ ವ್ಯಕ್ತಿಯಾಗಬೇಕೆಂದು ಬಯಸಿದ್ದರು."),
        "dua_visiting_graves" to DuaText("ಸಮಾಧಿಗಳಿಗೆ ಭೇಟಿ", "ಓ ಈ ಮನೆಗಳಲ್ಲಿರುವ ನಂಬಿಕೆಯುಳ್ಳವರೇ, ಮುಸ್ಲಿಮರೇ, ನಿಮಗೆ ಶಾಂತಿ ಇರಲಿ. ಅಲ್ಲಾಹನು ಬಯಸಿದರೆ ನಾವೂ ನಿಮ್ಮೊಂದಿಗೆ ಸೇರಿಕೊಳ್ಳುತ್ತೇವೆ. ನಮಗೂ ಮತ್ತು ನಿಮಗೂ ಒಳ್ಳೆಯದಾಗಲಿ ಎಂದು ನಾನು ಅಲ್ಲಾಹನನ್ನು ಬೇಡಿಕೊಳ್ಳುತ್ತೇನೆ.", "ಸ್ಮಶಾನವನ್ನು ಪ್ರವೇಶಿಸುವಾಗ.", "ಸಮಾಧಿಗಳಿಗೆ ಭೇಟಿ ನೀಡುವುದು ಸಾವು ಮತ್ತು ಪರಕಾಲವನ್ನು ನೆನಪಿಸುತ್ತದೆ."),
        "dua_closing_eyes" to DuaText("ಮೃತರ ಕಣ್ಣುಗಳನ್ನು ಮುಚ್ಚಿದ ನಂತರ", "ಓ ಅಲ್ಲಾಹನೇ, (ಹೆಸರು) ಕ್ಷಮಿಸು, ಮಾರ್ಗದರ್ಶಿಗಳಲ್ಲಿ ಅವನ ಶ್ರೇಣಿಯನ್ನು ಹೆಚ್ಚಿಸು, ಅವನು ಬಿಟ್ಟುಹೋದವರಲ್ಲಿ ಅವನ ಉತ್ತರಾಧಿಕಾರಿಯಾಗು. ಓ ಲೋಕಗಳ ಒಡೆಯನೇ, ನಮ್ಮನ್ನು ಮತ್ತು ಅವನನ್ನು ಕ್ಷಮಿಸು, ಅವನ ಸಮಾಧಿಯನ್ನು ವಿಶಾಲಗೊಳಿಸಿ ಮತ್ತು ಅದನ್ನು ಬೆಳಕಿನಿಂದ ತುಂಬಿಸು.", "ಮೃತರ ಕಣ್ಣುಗಳನ್ನು ಮುಚ್ಚುವಾಗ (ಅವರ ಹೆಸರನ್ನು ಉಲ್ಲೇಖಿಸುವುದು).", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಅಬು ಸಲಮಾ (ರ.) ಗಾಗಿ ಈ ದುಆವನ್ನು ಮಾಡಿದರು."),
        "dua_condolence" to DuaText("ಸಂತಾಪ (ತಾಜಿಯಾ)", "ಖಂಡಿತವಾಗಿಯೂ ಅಲ್ಲಾಹನೇ ತೆಗೆದುಕೊಂಡದ್ದು ಅವನಿಗೆ ಸೇರಿದ್ದು ಮತ್ತು ಅವನು ಕೊಟ್ಟದ್ದು ಅವನಿಗೆ ಸೇರಿದ್ದು, ಮತ್ತು ಅವನ ಬಳಿ ಇರುವ ಪ್ರತಿಯೊಂದಕ್ಕೂ ಒಂದು ನಿರ್ದಿಷ್ಟ ಅವಧಿಯಿರುತ್ತದೆ, ಆದ್ದರಿಂದ ತಾಳ್ಮೆಯಿಂದಿರಿ ಮತ್ತು ಪ್ರತಿಫಲವನ್ನು ನಿರೀಕ್ಷಿಸಿ.", "ಅವರ ನಿಧನದ ನಂತರ ಕುಟುಂಬಕ್ಕೆ ಸಂತಾಪ ಸೂಚಿಸಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಈ ಸಂದೇಶವನ್ನು ತಮ್ಮ ಮಗಳಿಗೆ ಕಳುಹಿಸಿದ್ದಾರೆ."),
        "dua_placing_in_grave" to DuaText("ಮೃತರನ್ನು ಸಮಾಧಿಯಲ್ಲಿ ಇರಿಸುವುದು", "ಅಲ್ಲಾಹ್ನ ಹೆಸರಿನಲ್ಲಿ ಮತ್ತು ಅಲ್ಲಾಹ್ನ ದೂತನ ಮಾರ್ಗದಲ್ಲಿ.", "ಮೃತರನ್ನು ಸಮಾಧಿಗೆ ಇಳಿಸುವಾಗ.", "ಸಮಾಧಿ ಮಾಡುವ ಸುನ್ನಹ್ ದುಆ."),
        "dua_sneezing" to DuaText("ಸೀನು", "ಎಲ್ಲಾ ಸ್ತುತಿಯೂ ಅಲ್ಲಾಹನಿಗೇ.-ಅಲ್ಲಾಹನು ನಿನ್ನನ್ನು ಕರುಣಿಸಲಿ.-ಅಲ್ಲಾಹನು ನಿನಗೆ ಮಾರ್ಗದರ್ಶನ ಮಾಡಲಿ ಮತ್ತು ನಿನ್ನ ವ್ಯವಹಾರಗಳನ್ನು ಸರಿಪಡಿಸಿ.", "ಸೀನಿಸಿದಾಗ ಕೇಳುಗನು'ಯಾರಹಮುಕಲ್ಲಾ'ಎಂದು ಹೇಳುತ್ತಾನೆ, ನಂತರ ಸೀನಿಸಿದವನು ಉತ್ತರಿಸುತ್ತಾನೆ.", "ಇದು ಮತ್ತೊಬ್ಬ ಮುಸ್ಲಿಮನ ಮೇಲೆ ಮುಸ್ಲಿಮನ ಹಕ್ಕುಗಳಲ್ಲಿ ಒಂದಾಗಿದೆ."),
        "dua_toilet_enter" to DuaText("ಶೌಚಾಲಯದೊಳಗೆ ಪ್ರವೇಶ", "ಅಲ್ಲಾಹ್ನ ಹೆಸರಿನಲ್ಲಿ. ಓ ಅಲ್ಲಾಹನೇ, ನಾನು ಅಶುದ್ಧ ಜಿನ್ನರಿಗಿಂತ ನಿನ್ನಲ್ಲಿ ಆಶ್ರಯವನ್ನು ಕೋರುತ್ತೇನೆ.", "ಶೌಚಾಲಯಕ್ಕೆ ಕಾಲಿಡುವ ಮೊದಲು ಎಡ ಪಾದವನ್ನು ಹಿಡಿದುಕೊಳ್ಳಿ.", "ಬಿಸ್ಮಿಲ್ಲಾವು ಜಿನ್ನರು ಮತ್ತು ವ್ಯಕ್ತಿಯ ನಡುವಿನ ಪರದೆಯಾಗುತ್ತದೆ."),
        "dua_toilet_exit" to DuaText("ಶೌಚಾಲಯದಿಂದ ಹೊರಹೋಗುವುದು", "(ಓ ಅಲ್ಲಾಹನೇ,) ನಾನು ನಿನ್ನನ್ನು ಕ್ಷಮಿಸುತ್ತೇನೆ.", "ಶೌಚಾಲಯದಿಂದ ಹೊರಬರುವಾಗ ಬಲ ಪಾದವನ್ನು ಹಿಡಿದುಕೊಳ್ಳಿ.", "ಪ್ರವಾದಿ ಸಲ್ಲಲ್ಲಾಹು ಅಲೈಹಿ ವಸಲ್ಲಮ್ ಅವರು ಶೌಚಾಲಯದಿಂದ ಹೊರಬಂದಾಗ ಇದನ್ನು ಹೇಳಿದರು."),
        "dua_thanking" to DuaText("ಯಾರಿಗಾದರೂ ಕೃತಜ್ಞತೆ ಸಲ್ಲಿಸುವುದು.", "ಅಲ್ಲಾಹ್ ನಿಮಗೆ ಒಳ್ಳೆಯದನ್ನು ಪ್ರತಿಫಲಿಸಲಿ.", "ಯಾರಾದರೂ ನಿಮಗೆ ಉಪಕಾರ ಮಾಡಿದಾಗ.", "ಇದನ್ನು ಯಾರು ಹೇಳಿದರೂ ಅವರು ತಮ್ಮ ಕೃತಜ್ಞತೆಯನ್ನು ವ್ಯಕ್ತಪಡಿಸಿದ್ದಾರೆ."),
        "dua_love_for_allah" to DuaText("ಯಾರಾದರೂ'ಐ ಲವ್ ಯು ಫಾರ್ ಅಲ್ಲಾಹ್'ಎಂದು ಹೇಳಿದಾಗ", "ನೀವು ನನ್ನನ್ನು ಯಾರ ನಿಮಿತ್ತ ಪ್ರೀತಿಸುತ್ತೀರೋ ಆತನು (ಅಲ್ಲಾಹ್) ನಿಮ್ಮನ್ನು ಪ್ರೀತಿಸಲಿ.", "ಯಾರಾದರೂ'ಅಲ್ಲಾಹನಿಗಾಗಿ ನಾನು ನಿನ್ನನ್ನು ಪ್ರೀತಿಸುತ್ತೇನೆ'ಎಂದು ಹೇಳಿದಾಗ.", "ಅಲ್ಲಾಹುವಿನ ಪರವಾಗಿ ಇರುವ ಪ್ರೀತಿಗೆ ಸುನ್ನತವು ಉತ್ತರಿಸುತ್ತದೆ."),
        "dua_seeing_muslim_smile" to DuaText("ಶುಭಾಶಯಗಳು (ಸಲಾಂ)", "ನಿಮಗೆ ಶಾಂತಿ ಮತ್ತು ಅಲ್ಲಾಹುವಿನ ಕರುಣೆ ಮತ್ತು ಆತನ ಆಶೀರ್ವಾದಗಳು ಇರಲಿ.", "ಒಬ್ಬ ಮುಸ್ಲಿಮನನ್ನು ಭೇಟಿಯಾದಾಗ.", "ಸಂಪೂರ್ಣ ಸಲಾಂ ಹೇಳುವುದರಿಂದ ಮೂವತ್ತು ಒಳ್ಳೆಯ ಕಾರ್ಯಗಳು ಗಳಿಸುತ್ತವೆ."),
        "dua_dressing" to DuaText("ಬಟ್ಟೆ ಧರಿಸುವುದು", "ನನಗೆ ಇದನ್ನು ಧರಿಸಿ, ನನ್ನ ಕಡೆಯಿಂದ ಯಾವುದೇ ಶಕ್ತಿ ಅಥವಾ ಶಕ್ತಿಯಿಲ್ಲದೆ ನನಗೆ ಅದನ್ನು ಒದಗಿಸಿದ ಅಲ್ಲಾಹನಿಗಾಗಿ ಎಲ್ಲಾ ಪ್ರಶಂಸೆಗಳು.", "ಬಟ್ಟೆ ಧರಿಸುವಾಗ.", "ಹಿಂದಿನ ಪಾಪಗಳ ಕ್ಷಮೆಗಾಗಿ ಶುಭ ಸುದ್ದಿ."),
    )
}
